/**
 * Shared OpenTelemetry types and the helpers the bake-time providers use.
 * Export itself lives in `customer.ts`.
 */
import { DiagLogLevel, diag, trace, } from "@opentelemetry/api";
import { AggregationTemporalityPreference, CumulativeTemporalitySelector, DeltaTemporalitySelector, LowMemoryTemporalitySelector, } from "@opentelemetry/exporter-metrics-otlp-http";
import { egressAllowsHost } from "../hosting.js";
/**
 * Hosted v2 pods may be frozen or destroyed as soon as the HTTP reply
 * lands. Bound the exporter wait so a slow collector cannot hold the
 * delivery (OTLP BatchSpanProcessor defaults to 30s).
 */
export const OTEL_FORCE_FLUSH_TIMEOUT_MS = 1_000;
export async function raceOtelForceFlush(work, log, timeoutMs = OTEL_FORCE_FLUSH_TIMEOUT_MS) {
    let timer;
    const timeout = new Promise((resolve) => {
        timer = setTimeout(() => resolve("timeout"), timeoutMs);
    });
    const result = await Promise.race([
        work.then(() => "done").catch(() => "done"),
        timeout,
    ]);
    if (timer !== undefined) {
        clearTimeout(timer);
    }
    if (result === "timeout") {
        log(`[bdk:otel] forceFlush exceeded ${timeoutMs}ms; continuing`);
    }
}
export function installOtelDiagLogger(log) {
    diag.setLogger({
        verbose: (message) => log(`[bdk:otel] ${message}`),
        debug: (message) => log(`[bdk:otel] ${message}`),
        info: (message) => log(`[bdk:otel] ${message}`),
        warn: (message) => log(`[bdk:otel] warn: ${message}`),
        error: (message) => log(`[bdk:otel] error: ${message}`),
    }, DiagLogLevel.ERROR);
}
export function warnEgress(config, egressDomains, log) {
    if (egressDomains === undefined) {
        return;
    }
    for (const exporter of config.exporters) {
        if (!URL.canParse(exporter.url)) {
            continue;
        }
        const host = new URL(exporter.url).hostname;
        if (!egressAllowsHost(egressDomains, host)) {
            log(`[bdk:otel] error: exporter host ${host} is not in hosting.egressDomains; add the host and redeploy`);
        }
    }
}
export function metricTemporalityPreference(metricsConfig, log) {
    if (metricsConfig.unrecognizedTemporality !== undefined) {
        log(`[bdk:otel] warn: OTEL_EXPORTER_OTLP_METRICS_TEMPORALITY_PREFERENCE='${metricsConfig.unrecognizedTemporality}' is not cumulative, delta, or lowmemory; using delta`);
    }
    return aggregationTemporalityPreference(metricsConfig.temporality);
}
export function metricTemporalitySelector(temporality) {
    switch (temporality) {
        case "cumulative":
            return CumulativeTemporalitySelector;
        case "lowmemory":
            return LowMemoryTemporalitySelector;
        case "delta":
            return DeltaTemporalitySelector;
        default: {
            const exhaustive = temporality;
            return exhaustive;
        }
    }
}
/** True when a non-noop TracerProvider already owns the process. */
export function hasRealTracerProvider() {
    const provider = trace.getTracerProvider();
    if (!("getDelegate" in provider) || typeof provider.getDelegate !== "function") {
        return false;
    }
    const delegate = provider.getDelegate();
    return (typeof delegate === "object" &&
        delegate !== null &&
        "constructor" in delegate &&
        typeof delegate.constructor === "function" &&
        delegate.constructor.name !== "NoopTracerProvider");
}
function aggregationTemporalityPreference(temporality) {
    switch (temporality) {
        case "cumulative":
            return AggregationTemporalityPreference.CUMULATIVE;
        case "delta":
            return AggregationTemporalityPreference.DELTA;
        case "lowmemory":
            return AggregationTemporalityPreference.LOWMEMORY;
        default: {
            const exhaustive = temporality;
            return exhaustive;
        }
    }
}
